using System.Security.Claims;using LocalPro.Web.Data;using LocalPro.Web.Domain;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;
namespace LocalPro.Web.Pages;
[Authorize(Roles="Admin")]public class AdminModel(AppDbContext db):PageModel{public List<Domain.Professional> Profiles{get;set;}=[];public List<UserReport> Reports{get;set;}=[];public List<Category> Categories{get;set;}=[];public int Users{get;set;}public int Bookings{get;set;}public List<AuditEvent> Events{get;set;}=[];
 public async Task OnGetAsync(){Reports=await db.Reports.OrderBy(r=>r.Resolved).ThenByDescending(r=>r.CreatedUtc).Take(100).ToListAsync();Profiles=await db.Professionals.Include(p=>p.Category).OrderBy(p=>p.Approved).ToListAsync();Categories=await db.Categories.ToListAsync();Users=await db.Users.CountAsync();Bookings=await db.Appointments.CountAsync();Events=await db.AuditEvents.OrderByDescending(a=>a.CreatedUtc).Take(20).ToListAsync();}
 public async Task<IActionResult> OnPostApprovalAsync(int id,bool approve){var p=await db.Professionals.FindAsync(id);if(p==null)return NotFound();p.Approved=approve;db.AuditEvents.Add(new(){ActorId=User.FindFirstValue(ClaimTypes.NameIdentifier)!,Action=$"Profile {id}: {(approve?"approved":"suspended")}"});await db.SaveChangesAsync();return RedirectToPage();}
 public async Task<IActionResult> OnPostResolveAsync(int id){var report=await db.Reports.FindAsync(id);if(report==null)return NotFound();report.Resolved=true;db.AuditEvents.Add(new(){ActorId=User.FindFirstValue(ClaimTypes.NameIdentifier)!,Action=$"Report {id} resolved"});await db.SaveChangesAsync();return RedirectToPage();}
 public async Task<IActionResult> OnPostCategoryAsync(string name){if(!string.IsNullOrWhiteSpace(name)&&name.Length<=80&&!await db.Categories.AnyAsync(c=>c.Name==name)){db.Categories.Add(new(){Name=name.Trim(),Icon="⌘"});db.AuditEvents.Add(new(){ActorId=User.FindFirstValue(ClaimTypes.NameIdentifier)!,Action=$"Category added: {name.Trim()}"});await db.SaveChangesAsync();}return RedirectToPage();}}
